"""Walk-through of lesson 29, Service Discovery & Gateways.

Example numbers (mine, checked by script): Orders makes 100 calls a second to Payments, which runs 3 instances: 33.3 calls a second to each.
One crashed instance with a stale address: 1 call in 3 fails = 33 a second; an hour of that = 120,000 failed calls.
Heartbeat every 5 s; dropped after 3 missed beats = 15 s: 33.3 x 15 = 500 failed calls. A client that caches a DNS answer for 60 s: 33.3 x 60 = 2,000.
A new instance that registers before it is ready (30 s) while it gets a third of the traffic: 33.3 x 30 = 1,000 failed calls.
"""
from walkkit import node, sh, ln, st, walk

NODES = [
    node("or", "service", ("Orders", "Orders"), 90, 170),
    node("reg", "database", ("Registry", "Registry"), 350, 290),
    node("pa-a", "service", ("Payments A", "Payments A"), 620, 60),
    node("pa-b", "service", ("Payments B", "Payments B"), 620, 170),
    node("pa-c", "service", ("Payments C", "Payments C"), 620, 280),
    node("pa-d", "service", ("Payments D", "Payments D"), 410, 285),
    node("n-client", "note", ("Client-side", "Client-side"), 190, 170),
    node("n-server", "note", ("Server-side", "Server-side"), 570, 170),
    node("dns", "dns", ("DNS", "DNS"), 350, 60),
    node("rg-a", "database", ("Registry A", "Registry A"), 150, 300),
    node("rg-b", "database", ("Registry B", "Registry B"), 290, 300),
    node("rg-c", "database", ("Registry C", "Registry C"), 430, 300),
    node("n-plumb", "note", ("Retries, TLS, metrics", "Retry, TLS, metrics"), 380, 60),
    node("s-us", "service", ("Users", "Users"), 150, 230),
    node("s-or", "service", ("Orders", "Orders"), 380, 230),
    node("s-pa", "service", ("Payments", "Payments"), 610, 230),
    node("m-or", "service", ("Orders", "Orders"), 85, 170),
    node("m-so", "shield", ("Sidecar", "Sidecar"), 255, 170),
    node("m-sp", "shield", ("Sidecar", "Sidecar"), 505, 170),
    node("m-pa", "service", ("Payments", "Payments"), 675, 170),
    node("cp", "service", ("Control plane", "Control plane"), 380, 50),
    node("app", "user", ("Mobile app", "মোবাইল app"), 85, 80),
    node("web", "browser", ("Browser", "ব্রাউজার"), 85, 260),
    node("gw", "balancer", ("API gateway", "API gateway"), 330, 170),
]
METRICS = [("Failed calls", "ব্যর্থ call"), ("Instances", "Instance"), ("Lookup", "Lookup")]
CAPTION = ("Example numbers: Orders makes 100 calls a second to Payments, which runs 3 instances. Heartbeats come every 5 seconds.",
           "উদাহরণের সংখ্যা: Orders সেকেন্ডে ১০০ call করে Payments-কে, যে চালায় ৩টি instance। Heartbeat আসে প্রতি ৫ সেকেন্ডে।")

CONFIG = ("config file", "config file")
REGISTRY = ("registry", "registry")
THREE = [("pa-a", 60), ("pa-b", 170), ("pa-c", 280)]


def calls(state="hot"):
    return [ln("or", p, "to", 1100, state) for p, _ in THREE]


def beats(state="hot"):
    return [ln(p, "reg", "to", 1500, state) for p, _ in THREE]


